files.manifest.json:
{
  "name": "answer_body_measurement_statistics_question",
  "kind": "workflow",
  "description": "Answers general-knowledge questions about average human anatomical measurements by region from published research, with sources and uncertainty.",
  "signature": {
    "in": "{\"type\":\"object\",\"properties\":{\"region\":{\"type\":\"string\"},\"measure\":{\"type\":\"string\"},\"unit\":{\"type\":\"string\"},\"question\":{\"type\":\"string\"}},\"required\":[\"region\",\"measure\"]}",
    "out": "output of s1"
  },
  "steps": [
    {
      "id": "s1",
      "uses": "answer_from_published_knowledge",
      "foreach": null,
      "inputs": [
        {
          "param": "region",
          "source": "$input.region"
        },
        {
          "param": "measure",
          "source": "$input.measure"
        },
        {
          "param": "unit",
          "source": "$input.unit"
        },
        {
          "param": "question",
          "source": "$input.question"
        }
      ]
    }
  ],
  "output_step": "s1",
  "permissions": {
    "net": [],
    "llm": true
  },
  "budget": {
    "max_tokens_per_run": 6000
  },
  "lineage": {
    "created_by": "factory",
    "uses": [
      "answer_from_published_knowledge@v1"
    ]
  },
  "example_input": "{\"region\":\"Europe\",\"measure\":\"average erect penis length\",\"unit\":\"cm\",\"question\":\"What is the average penis size in Europe?\"}",
  "purpose": "average penis size in europe",
  "version": 1,
  "headline": "{answer}",
  "examples": [
    "What is the average penis size in Europe?",
    "Are self-reported penis sizes bigger than measured ones?",
    "How reliable are studies on average erect length in European men?"
  ]
}

